const sentenceAt=(text,n)=>{const sentences=text.match(/[^。！？]+[。！？]?/g)||[text];return sentences[Math.min(n,sentences.length-1)];};
export function combinedTypePoints(code){const story=typeStories[code];if(!story)return null;const labels=workLabels[code];const sources=[story.chapters.work[0],story.scene,story.chapters.work[1],story.practice];return labels.map(([strength,risk],i)=>({axis:'类型组合',strength,risk,detail:sentenceAt(sources[i],0),riskDetail:sentenceAt([story.friction,story.chapters.work[1],story.friction,story.chapters.work[1]][i],i%2),action:sentenceAt(story.practice,i)}));}
export function independentTypeSummary(code,chapter,dimensions){
 const story=typeStories[code];if(!story)return null;
 if(code==='INTP')return editedIntp[chapter].join('\n\n');
 const [first,second]=story.chapters[chapter],pressure=dimensions[4];
 const pressureContext=pressure.boundary?'你面对压力时的两边得分很接近。遇到不同的事、精力不同，你的反应也可能不一样，不必急着给自己定性。':pressure.letter==='A'?'你这次的回答偏向遇事较从容，可能更容易继续做下去。不过，觉得自己还能应付，也别忘了看看是不是已经累了，听听别人有什么提醒。':'你这次的回答偏向比较在意评价和失误。认真检查能帮助你改进，但也可以提前约定：检查到什么程度就先停下，不必一直担心自己还漏了什么。';
 const firstContext={traits:`回想一下最近让你特别投入的一件事，也许你当时就在${story.focus}。至于一次没做好的选择，也不必都归结为性格；当时有没有时间、是否熟悉那件事，同样会影响表现。`,work:`看一份工作时，可以问问自己：每天做的事情，能不能让你${story.focus}？岗位名字一样，换一个团队，日常安排也可能差很多。提前问清楚，比只看职位介绍更接近实际。`,growth:`不妨从最近一件没做顺的事开始，想想自己是在什么地方卡住了。是还不会、没有时间，还是其实不愿意？先分清原因，再决定要多练一点、向人求助，还是换个做法。`,relations:`两个人都在关心对方，也可能因为表达方式不同而觉得委屈。你以为是在帮忙，他可能更想先被听见；你觉得已经说清楚，他可能还需要一点时间。与其互相猜，不如直接问问这一次各自需要什么。`}[chapter];
 const sceneContext={traits:story.scene,work:story.scene,growth:story.chapters.traits[1],relations:story.chapters.traits[0]}[chapter];
 const secondContext={traits:story.friction+story.practice,work:story.friction+story.practice,growth:story.practice+story.friction,relations:story.friction+story.practice}[chapter];
 return first+sceneContext+firstContext+'\n\n'+second+secondContext+pressureContext;
}
